function fechaISO(value) {
 if (typeof value !== 'string') return null;
 const s=value.trim().toLowerCase(); let y,m,d; let a=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
 if(a) [,y,m,d]=a; else {a=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/); if(a) [,d,m,y]=a; else { a=s.match(/^(\d{1,2})\s+(?:de\s+)?(ene(?:ro)?|feb(?:rero)?|mar(?:zo)?|abr(?:il)?|may(?:o)?|jun(?:io)?|jul(?:io)?|ago(?:sto)?|sep(?:tiembre)?|oct(?:ubre)?|nov(?:iembre)?|dic(?:iembre)?)\s+(?:de\s+)?(\d{4})$/); if(!a) return null; d=a[1];y=a[3];m=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'].indexOf(a[2].slice(0,3))+1; }}
 y=+y;m=+m;d=+d;let dt=new Date(Date.UTC(y,m-1,d)); if(dt.getUTCFullYear()!==y||dt.getUTCMonth()+1!==m||dt.getUTCDate()!==d)return null; return `${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
}
function importeNumero(v) {
 if(typeof v==='number') return Number.isFinite(v)?v:null;
 if(typeof v!=='string') return null;
 let s=v.trim().replace(/^(?:ARS|USD|EUR|\$|€)\s*/i,'').replace(/\s*(?:ARS|USD|EUR)$/i,'').trim();
 if (/^-?\d{1,3}(?:\.\d{3})+,\d{2}$/.test(s)) s=s.replace(/\./g,'').replace(',','.');
 else if (/^-?\d{1,3}(?:,\d{3})+\.\d{2}$/.test(s)) s=s.replace(/,/g,'');
 else if (/^-?\d+,\d{1,2}$/.test(s)) s=s.replace(',','.');
 else if (!/^-?\d+(?:\.\d{1,2})?$/.test(s)) return null;
 const n=Number(s);return Number.isFinite(n)?n:null;
}
